import { now, mulberry32, hashString, mark, nextTask, loadScript, runSafe } from "./util.js";

const INTERACTION_TICKS = 8;
const TARGETING_KEYS = 200;
const CAP_KEYS_PER_SLOT = 3;
const ANCESTOR_DEPTH = 10;
const ANCESTOR_ATTRIBUTES = ["data-section", "data-commercial-slot", "data-testid"];
const REFRESH_EVERY_CLICKS = 8;
const MAX_REFRESHES_PER_SLOT = 2;
const AUCTION_TIMEOUT = 3000;
const CONSENT_TIMEOUT = 8000;
const LAZY_FETCH_MARGIN_PERCENT = 150;
const LAZY_RENDER_MARGIN_PERCENT = 100;
const STATE_KEY_PREFIX = "adtag:cap:";

export function createEngine({ config, slots }) {
    const random = mulberry32(hashString(config.pageType + config.release));
    const pageTargeting = new Map();
    const defaultTargeting = new Map();
    const slotTargeting = new Map();
    const adserverSlots = new Map();
    const refreshCounts = new Map();
    const viewable = [];
    let clickCount = 0;
    let configured = false;

    function seedTargeting() {
        for (const [key, value] of Object.entries(config.targeting))
            defaultTargeting.set(key, value);
        for (let i = 0; i < TARGETING_KEYS; i++)
            defaultTargeting.set("k" + i, String(hashString("default" + i) % 997));
        for (const slot of slots) {
            const map = new Map();
            map.set("pos", slot.definition.position);
            map.set("name", slot.name);
            map.set("sz", slot.sizes.map((size) => size.join("x")).join(","));
            for (let i = 0; i < TARGETING_KEYS; i += 4)
                map.set("k" + i, String((hashString(slot.name) + i) % 211));
            slotTargeting.set(slot.name, map);
        }
    }

    function collectPageTargeting() {
        const head = document.head;
        const words = new Map();
        const description = head.querySelector('meta[name="description"]');
        const keywords = head.querySelector('meta[name="keywords"]');
        const source = [document.title, description && description.content, keywords && keywords.content].join(" ");
        for (const word of source.toLowerCase().split(/[^a-zäöüß0-9]+/)) {
            if (word.length > 4)
                words.set(word, (words.get(word) || 0) + 1);
        }
        const topWords = [...words.entries()].sort((a, b) => b[1] - a[1] || (a[0] < b[0] ? -1 : 1)).slice(0, 5).map((entry) => entry[0]);
        const segments = location.pathname.split("/").filter(Boolean);
        pageTargeting.set("pt", config.pageType);
        pageTargeting.set("path", segments.slice(0, 2).join("_") || "home");
        pageTargeting.set("kw", topWords.join(","));
        pageTargeting.set("ts", String(Math.floor(now() / 3600000)));
        pageTargeting.set("rnd", String(Math.floor(random() * 100)));
        for (const [key, value] of defaultTargeting) {
            if (!pageTargeting.has(key) && key.indexOf("k") !== 0)
                pageTargeting.set(key, value);
        }
    }

    function resolveKey(slotName, key) {
        const own = slotTargeting.get(slotName);
        if (own && own.has(key))
            return own.get(key);
        if (pageTargeting.has(key))
            return pageTargeting.get(key);
        return defaultTargeting.get(key);
    }

    function adUnit(slot) {
        return {
            code: slot.id,
            mediaTypes: { banner: { sizes: slot.sizes } },
            ortb2Imp: { ext: { data: { adslot: config.adUnitPath + "/" + slot.name } } },
            bids: slot.definition.bidders.map((bidder) => ({
                bidder,
                params: { slot: slot.name, placementId: slot.placements[bidder] },
            })),
        };
    }

    function configurePrebid(pbjs) {
        if (configured)
            return;
        configured = true;
        const prebid = config.prebid;
        pbjs.setConfig({
            bidderTimeout: AUCTION_TIMEOUT,
            priceGranularity: "dense",
            enableSendAllBids: true,
            useBidCache: true,
            consentManagement: { gdpr: { cmpApi: "iab", timeout: CONSENT_TIMEOUT, defaultGdprScope: true } },
            currency: { adServerCurrency: "EUR", rates: prebid.rates },
            floors: { enforcement: { floorDeals: true }, data: prebid.floors },
            userSync: { syncEnabled: false },
            ortb2: {
                site: { name: "portal", page: location.href, cat: [config.pageType] },
                source: { ext: { schain: prebid.schain } },
            },
        });
    }

    function auction(auctionSlots) {
        return new Promise((resolve) => {
            const pbjs = window.pbjs;
            pbjs.que.push(() => {
                configurePrebid(pbjs);
                const units = auctionSlots.map(adUnit);
                pbjs.addAdUnits(units);
                pbjs.requestBids({
                    adUnitCodes: units.map((unit) => unit.code),
                    timeout: AUCTION_TIMEOUT,
                    bidsBackHandler: (bids, timedOut) => {
                        const targeting = {};
                        for (const unit of units)
                            targeting[unit.code] = pbjs.getAdserverTargetingForAdUnitCode(unit.code) || {};
                        resolve({ bids, timedOut, targeting });
                    },
                });
            });
        });
    }

    function applyBidTargeting(slot, result) {
        const adserverSlot = adserverSlots.get(slot.name);
        const values = result.targeting[slot.id] || {};
        for (const key of Object.keys(values))
            adserverSlot.setTargeting(key, values[key]);
    }

    function render(result) {
        return new Promise((resolve) => {
            const adserver = window.adserver;
            let remaining = slots.filter((slot) => !slot.lazy).length;
            if (!remaining)
                resolve();
            adserver.cmd.push(() => {
                const pubads = adserver.pubads();
                pubads.enableSingleRequest();
                pubads.enableLazyLoad({
                    fetchMarginPercent: LAZY_FETCH_MARGIN_PERCENT,
                    renderMarginPercent: LAZY_RENDER_MARGIN_PERCENT,
                });
                for (const [key, value] of pageTargeting)
                    pubads.setTargeting(key, value);
                pubads.addEventListener("slotRenderEnded", (event) => {
                    const id = event.slot.getSlotElementId();
                    const slot = slots.find((candidate) => candidate.id === id);
                    mark("slot-" + (slot ? slot.name : id) + "-rendered");
                    if (slot && !slot.lazy && --remaining === 0)
                        resolve();
                });
                pubads.addEventListener("impressionViewable", (event) => {
                    viewable.push(event.slot.getSlotElementId());
                });
                for (const slot of slots) {
                    const adserverSlot = adserver.defineSlot(config.adUnitPath + "/" + slot.name, slot.sizes, slot.id);
                    adserverSlots.set(slot.name, adserverSlot);
                    adserverSlot.addService(pubads);
                    adserverSlot.setConfig({ lazy: slot.lazy });
                    for (const [key, value] of slotTargeting.get(slot.name))
                        adserverSlot.setTargeting(key, value);
                    applyBidTargeting(slot, result);
                }
                adserver.enableServices();
                for (const slot of slots)
                    adserver.display(slot.id);
            });
        });
    }

    function slotContext(element) {
        const context = {};
        let node = element;
        for (let depth = 0; node && depth < ANCESTOR_DEPTH; depth++) {
            for (const name of ANCESTOR_ATTRIBUTES) {
                const value = node.getAttribute(name);
                if (value !== null && !(name in context))
                    context[name] = value;
            }
            node = node.parentElement;
        }
        return context;
    }

    function tick(slot) {
        const context = slotContext(slot.element);
        let checksum = 0;
        for (let i = 0; i < TARGETING_KEYS; i++) {
            const value = resolveKey(slot.name, "k" + i);
            checksum = (checksum + value.length) | 0;
        }
        const record = { checksum, section: context["data-section"] || "", shown: viewable.length };
        for (let i = 0; i < CAP_KEYS_PER_SLOT; i++) {
            const stored = localStorage.getItem(STATE_KEY_PREFIX + slot.name + ":" + i);
            if (stored) {
                const parsed = JSON.parse(stored);
                record.shown += parsed.n | 0;
            }
        }
        return JSON.stringify(record).length;
    }

    function persistCaps() {
        for (const slot of slots) {
            const payload = JSON.stringify({ n: clickCount, t: Math.floor(now() / 1000) });
            localStorage.setItem(STATE_KEY_PREFIX + slot.name + ":0", payload);
            localStorage.setItem(STATE_KEY_PREFIX + slot.name + ":1", payload);
            localStorage.setItem(STATE_KEY_PREFIX + slot.name + ":2", payload);
        }
    }

    function nextRefreshCandidate() {
        for (const id of viewable) {
            const slot = slots.find((candidate) => candidate.id === id);
            if (slot && (refreshCounts.get(slot.name) || 0) < MAX_REFRESHES_PER_SLOT)
                return slot;
        }
        return null;
    }

    function refreshSlot(slot) {
        refreshCounts.set(slot.name, (refreshCounts.get(slot.name) || 0) + 1);
        return (async () => {
            mark("refresh-" + slot.name + "-start");
            const result = await auction([slot]);
            const adserverSlot = adserverSlots.get(slot.name);
            applyBidTargeting(slot, result);
            adserverSlot.setTargeting("refresh", String(refreshCounts.get(slot.name)));
            await new Promise((resolve) => {
                window.adserver.cmd.push(() => {
                    window.adserver.pubads().refresh([adserverSlot]);
                    resolve();
                });
            });
            await nextTask();
            mark("refresh-" + slot.name + "-end");
        })();
    }

    const onClick = runSafe(function () {
        clickCount++;
        for (let i = 0; i < INTERACTION_TICKS; i++) {
            for (const slot of slots)
                tick(slot);
        }
        persistCaps();
        if (clickCount % REFRESH_EVERY_CLICKS === 0) {
            const candidate = nextRefreshCandidate();
            if (candidate)
                refreshSlot(candidate);
        }
    });

    async function run() {
        window.pbjs = window.pbjs || {};
        window.pbjs.que = window.pbjs.que || [];
        window.adserver = window.adserver || { cmd: [] };
        seedTargeting();
        mark("Phase-LOAD-start");
        await Promise.all([loadScript(config.scripts.adserver), loadScript(config.scripts.prebid)]);
        mark("Phase-LOAD-end");
        collectPageTargeting();
        mark("Phase-AUCTION-start");
        const result = await auction(slots);
        await nextTask();
        await nextTask();
        mark("Phase-AUCTION-end");
        mark("Phase-RENDER-start");
        await render(result);
        mark("Phase-RENDER-end");
        document.addEventListener("click", onClick, { capture: true, passive: true });
    }

    function refresh(name) {
        const slot = slots.find((candidate) => candidate.name === name);
        return slot && adserverSlots.has(name) ? refreshSlot(slot) : Promise.resolve();
    }

    return { run, refresh };
}
